[SrsReportParameterAttribute(classStr(FTDBookReportContract))]
public class FTDBookReportDataProvider extends SRSReportDataProviderBase
{
    FTDtmpAuthorTable headerAuthorInfo;
    FTDtmpBookTable lineBooksInfo;

}

Method.Source:
[SRSReportDataSetAttribute("headerAuthorInfo")] //Aquí indicamos la tabla temporal que usaremos como data para el controller
public FTDtmpAuthorTable getHeaderAuthorInfo()
{
    select * from headerAuthorInfo;
    return headerAuthorInfo;
}

[SRSReportDataSetAttribute("lineBooksInfo")] //Aquí indicamos la tabla temporal que usaremos como data para el controller
public FTDtmpBookTable getLineBooksInfo()
{
    select * from lineBooksInfo;
    return lineBooksInfo;
}

public void processReport()
{
    FTDBookReportContract bookReportContract = this.parmDataContract();

    super();

    FTDAuthorTable authorTable = FTDAuthorTable::find(bookReportContract.parmAuthorId());

    if (authorTable)
    {
        this.insertHeaderData(authorTable);
        this.insertLinesData(authorTable);
    }
    else
    {
        throw error("@ITFormacion:InvalidAuthor");
    }
}

private void insertHeaderData(FTDAuthorTable _author)
{
    headerAuthorInfo.clear();

    headerAuthorInfo.initFromAuthorTable(_author);

    if (headerAuthorInfo.validateWrite())
    {
        headerAuthorInfo.insert();
    }
    else
    {
        throw Exception::Error;
    }
}

private void insertLinesData(FTDAuthorTable _author)
{
    FTDBookTable book;

    while select book
        where book.Author == _author.RecId
    {
        this.insertLineData(book);
    }
}

private void insertLineData(FTDBookTable _book)
{
    lineBooksInfo.clear();

    lineBooksInfo.initFromtmpBookTable(_book);

    if (lineBooksInfo.validateWrite())
    {
        lineBooksInfo.insert();
    }
    else
    {
        throw Exception::Error;
    }
}
